-- =============================================================================
-- DDSE Migration: Module evaluation question templates
--
-- Adds a JSONB "template" blueprint to public.modules (sections + checklist
-- items transcribed from the DDSE evaluation handbook), and registers the
-- four modules from that handbook that had no corresponding module row yet.
-- create-inspection clones a module's template into inspection_sections /
-- inspection_items at inspection-creation time (see supabase/functions/
-- create-inspection), so every new evaluation starts pre-populated with the
-- real question set for its department instead of empty.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. Template column
-- ---------------------------------------------------------------------------
ALTER TABLE public.modules
  ADD COLUMN IF NOT EXISTS template jsonb NOT NULL DEFAULT '{"sections":[]}'::jsonb;

COMMENT ON COLUMN public.modules.template IS
  'Blueprint of {sections:[{title,items:[{code,prompt,responseType,weight}]}]} cloned into inspection_sections/inspection_items when a new inspection is created for this module.';

-- ---------------------------------------------------------------------------
-- 2. Register the new evaluation modules from the DDSE handbook
-- ---------------------------------------------------------------------------
INSERT INTO public.modules (code, title, description, classification) VALUES
  ('training_establishments', 'DHQ Training Establishments', 'Evaluation of training establishments — courses, staffing, facilities and outcomes', 'general'),
  ('afsb_nda', 'AFSB (NDA) Selection Board', 'Armed Forces Selection Board evaluation for the Nigerian Defence Academy', 'restricted_security'),
  ('civil_projects', 'Civil Projects Monitoring', 'Monitoring and evaluation of civil works, direct-labour projects and construction quality', 'general'),
  ('hazard_safety', 'Hazard / Safety Assessment', 'Workplace hazard and safety compliance checklist across facilities and operations', 'general')
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 3. Seed the template blueprint for every module (existing + new)
-- ---------------------------------------------------------------------------
UPDATE public.modules SET template = '{"sections":[{"title":"Training Establishment Profile","items":[{"code":"1","prompt":"How many departments does the establishment have?","responseType":"narrative","weight":10},{"code":"2","prompt":"How many courses does the department run?","responseType":"narrative","weight":10},{"code":"3","prompt":"How many years does each course last?","responseType":"narrative","weight":10},{"code":"4","prompt":"Are the courses approved by the National Board for Technical Education (NBTE), National University Commission (NUC), or another relevant professional/supervisory body?","responseType":"yes_no","weight":10},{"code":"5","prompt":"How many cadets/students/participants are enlisted for each course?","responseType":"narrative","weight":10},{"code":"6","prompt":"Are there members of other security services (sister services) personnel among the students?","responseType":"yes_no","weight":10},{"code":"7","prompt":"What percentage of students are from other security services?","responseType":"narrative","weight":10},{"code":"8","prompt":"What is the admission procedure?","responseType":"narrative","weight":10},{"code":"9","prompt":"Has DDSE been provided with the various course syllabi?","responseType":"yes_no","weight":10},{"code":"10","prompt":"How many classroom blocks are available for the courses run?","responseType":"narrative","weight":10},{"code":"11","prompt":"How many instructors/lecturers are there per course?","responseType":"narrative","weight":10},{"code":"12","prompt":"What is the academic qualification of the instructors?","responseType":"narrative","weight":10},{"code":"13","prompt":"Are the instructors/lecturers sufficient for the courses run?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Are instructors/lecturers paid their allowances promptly?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Is the present instructors/lecturers allowance adequate?","responseType":"yes_no","weight":10},{"code":"16","prompt":"Are the instructors/lecturers properly accommodated?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Do the teaching aids meet the professional body and NBTE specifications?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Is there a computer centre?","responseType":"yes_no","weight":10},{"code":"19","prompt":"How many computers are available and what is their serviceability?","responseType":"narrative","weight":10},{"code":"20","prompt":"Are cadets/students/participants properly accommodated and fed?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Are the laboratories well equipped and is the equipment maintained?","responseType":"yes_no","weight":10},{"code":"22","prompt":"How often are industrial visits organised for cadets/students/participants?","responseType":"narrative","weight":10},{"code":"23","prompt":"Do cadets/students/participants go for industrial attachments?","responseType":"yes_no","weight":10},{"code":"24","prompt":"Are the hospitals/organisations used for attachments approved by the relevant professional bodies?","responseType":"yes_no","weight":10},{"code":"25","prompt":"Does the establishment attend to patients in its various branches, and is a fee charged for this?","responseType":"yes_no","weight":10},{"code":"26","prompt":"What is done with money realised from any charged fee?","responseType":"narrative","weight":10},{"code":"27","prompt":"What were the cadets/students/participants results for the past five years?","responseType":"narrative","weight":10},{"code":"28","prompt":"Do cadets/students/participants write external exams before graduation?","responseType":"yes_no","weight":10},{"code":"29","prompt":"Are the department’s certificates recognised and registerable with the relevant professional body?","responseType":"yes_no","weight":10},{"code":"30","prompt":"How are practical materials sourced and how is training equipment maintained?","responseType":"narrative","weight":10},{"code":"31","prompt":"How much fund is available for local administration, and is it adequate?","responseType":"narrative","weight":10}]}]}'::jsonb WHERE code = 'training_establishments';
