UPDATE public.modules SET template = '{"sections":[{"title":"Standing Orders & Inspection Books","items":[{"code":"1","prompt":"Is there a standing orders document for the armoury?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are personnel on guard/sentry duty conversant with the standing orders?","responseType":"yes_no","weight":10},{"code":"3","prompt":"How often do guards relate to / refer back to the standing orders? (Very Often / Not Often / Not at All)","responseType":"narrative","weight":10},{"code":"4","prompt":"Is there an Armoury Inspection Book, and is it maintained regularly (Regular/Irregular)?","responseType":"yes_no","weight":10},{"code":"5","prompt":"How often do the appropriate authorities initial the Armoury Inspection Book to confirm their visits?","responseType":"narrative","weight":10},{"code":"6","prompt":"Is there a Daily Issue Book confirming movement of weapons in and out?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are there other books maintained besides the standing orders, inspection and daily issue books? If yes, name them.","responseType":"narrative","weight":10}]},{"title":"Guards & Sentries","items":[{"code":"1","prompt":"Are there guards/sentries posted at the armoury?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are the guards/sentries adequate in number (Adequate/Inadequate)?","responseType":"yes_no","weight":10},{"code":"3","prompt":"What is their strength (Less than one Section / One Section / More than a Section)?","responseType":"narrative","weight":10},{"code":"4","prompt":"How are they deployed (Centralized / Dispersed)?","responseType":"narrative","weight":10},{"code":"5","prompt":"For how many hours are they on duty (6 Hrs / 12 Hrs / 24 Hrs)?","responseType":"narrative","weight":10},{"code":"6","prompt":"How are the guards maintained/fed (Centrally Fed / Self Sustained or on RCA)?","responseType":"narrative","weight":10},{"code":"7","prompt":"What is the rotation plan — for how