seType":"narrative","weight":10},{"code":"3","prompt":"Annual medical test report","responseType":"score_5","weight":10},{"code":"4","prompt":"Annual PT test report","responseType":"score_5","weight":10},{"code":"5","prompt":"Physique (BMI)","responseType":"score_5","weight":10}]},{"title":"Regimental Activities","items":[{"code":"1","prompt":"Reveille","responseType":"score_5","weight":10},{"code":"2","prompt":"Morning PT/evening games","responseType":"score_5","weight":10},{"code":"3","prompt":"Route march","responseType":"score_5","weight":10},{"code":"4","prompt":"Commander’s parades","responseType":"score_5","weight":10},{"code":"5","prompt":"Barrack inspection","responseType":"score_5","weight":10},{"code":"6","prompt":"Tattoo/bugle calls","responseType":"score_5","weight":10},{"code":"7","prompt":"Records of ceremonies","responseType":"score_5","weight":10},{"code":"8","prompt":"Guard mounting","responseType":"score_5","weight":10},{"code":"9","prompt":"WASA","responseType":"score_5","weight":10},{"code":"10","prompt":"Orderly room procedure","responseType":"score_5","weight":10},{"code":"11","prompt":"Durbar","responseType":"score_5","weight":10},{"code":"12","prompt":"Inter-unit competitions — drill","responseType":"score_5","weight":10}]},{"title":"Discipline","items":[{"code":"1","prompt":"Minor offence book","responseType":"score_5","weight":10},{"code":"2","prompt":"Prevalent offences in the unit","responseType":"narrative","weight":10},{"code":"3","prompt":"Guard room entries","responseType":"score_5","weight":10},{"code":"4","prompt":"AWOL cases","responseType":"narrative","weight":10},{"code":"5","prompt":"Board of Inquiry / Regimental Inquiry records","responseType":"score_5","weight":10}]},{"title":"Drill Square","items":[{"code":"1","prompt":"Location of the parade ground","responseType":"score_5","weight":10},{"code":"2","prompt":"State of the parade ground","responseType":"score_5","weight":10},{"code":"3","prompt":"Marking of the parade ground","responseType":"score_5","weight":10},{"code":"4","prompt":"Saluting dias","responseType":"score_5","weight":10},{"code":"5","prompt":"Maintenance of the parade ground","responseType":"score_5","weight":10},{"code":"6","prompt":"Positioning of flags","responseType":"score_5","weight":10}]},{"title":"Range Classification","items":[{"code":"1","prompt":"Availability of a range area","responseType":"score_5","weight":10},{"code":"2","prompt":"Standard of the range","responseType":"score_5","weight":10},{"code":"3","prompt":"When was the range last classified?","responseType":"narrative","weight":10},{"code":"4","prompt":"Report of range classification available","responseType":"score_5","weight":10}]},{"title":"Mammy Market","items":[{"code":"1","prompt":"General cleanliness including layout","responseType":"score_5","weight":10},{"code":"2","prompt":"Illegal structures present","responseType":"score_5","weight":10},{"code":"3","prompt":"Drainage","responseType":"score_5","weight":10},{"code":"4","prompt":"Abattoir — neatness and disposal of refuse; availability of water drainage","responseType":"score_5","weight":10},{"code":"5","prompt":"Toilet facilities","responseType":"score_5","weight":10},{"code":"6","prompt":"Refuse collection and disposal","responseType":"score_5","weight":10},{"code":"7","prompt":"FFI certificate held by food service personnel and vendors","responseType":"score_5","weight":10},{"code":"8","prompt":"Food storage facilities","responseType":"score_5","weight":10},{"code":"9","prompt":"Signs of termite infestation of buildings","responseType":"score_5","weight":10}]}]}'::jsonb WHERE code = 'personnel';
UPDATE public.modules SET template = '{"sections":[{"title":"Attendance","items":[{"code":"1","prompt":"How many candidates were shortlisted?","responseType":"narrative","weight":10},{"code":"2","prompt":"How many candidates attended?","responseType":"narrative","weight":10},{"code":"3","prompt":"What were the reasons for those absent?","responseType":"narrative","weight":10},{"code":"4","prompt":"How many were screened out before interview?","responseType":"narrative","weight":10},{"code":"5","prompt":"How many faced the final interview?","responseType":"narrative","weight":10},{"code":"6","prompt":"How many made the final list?","responseType":"narrative","weight":10},{"code":"7","prompt":"How many were placed on the reserve list?","responseType":"narrative","weight":10}]},{"title":"Planning & Preparation","items":[{"code":"1","prompt":"Was the general instruction adequate and clear?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Were the questionnaires necessary for the candidates?","responseType":"yes_no","weight":10},{"code":"3","prompt":"What was the duration of the AFSB, and was it applicable/appropriate?","responseType":"narrative","weight":10},{"code":"4","prompt":"What were the criteria for shortlisting candidates?","responseType":"narrative","weight":10},{"code":"5","prompt":"What arrangements are in place for the reception of both panel members and candidates?","responseType":"narrative","weight":10},{"code":"6","prompt":"What were the criteria for screening and verification of candidates?","responseType":"narrative","weight":10},{"code":"7","prompt":"What is the competence level of those responsible for screening and verification of candidates?","responseType":"narrative","weight":10},{"code":"8","prompt":"What is the quality of infrastructure and facilities for medical screening, physical fitness test, aptitude test, psychological evaluation, field activities and oral interview?","responseType":"narrative","weight":10},{"code":"9","prompt":"Have lapses observed from the previous AFSB been addressed?","responseType":"yes_no","weight":10},{"code":"10","prompt":"What measures have been put in place to address the observed lapses?","responseType":"narrative","weight":10}]},{"title":"General Administration","items":[{"code":"1","prompt":"Exams/board location — is it suitable?","responseType":"yes_no","weight":10},{"code":"2","prompt":"What was the composition of the panel/directing staff (DS)?","responseType":"narrative","weight":10},{"code":"3","prompt":"What was the quality of the questions used?","responseType":"narrative","weight":10},{"code":"4","prompt":"Was the security of the questions maintained?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Was the arrangement of the secretariat satisfactory?","responseType":"yes_no","weight":10},{"code":"6","prompt":"How were the scripts marked?","responseType":"narrative","weight":10},{"code":"7","prompt":"What was the relationship between the panel and candidates?","responseType":"narrative","weight":10},{"code":"8","prompt":"How were results announced?","responseType":"narrative","weight":10},{"code":"9","prompt":"Was accommodation satisfactory?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Was feeding satisfactory?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Was finance for the panel/candidates handled adequately?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Was a wash-up (debrief) conducted?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are there any other administrative arrangements worth noting?","responseType":"narrative","weight":10}]}]}'::jsonb WHERE code = 'afsb_nda';
UPDATE public.modules SET template = '{"sections":[{"title":"SOP Compliance — Project Monitoring Procedure","items":[{"code":"1","prompt":"On award of civil contracts, did the Log Branch forward a copy of the contract to DDSE?","responseType":"yes_no","weight":10},{"code":"2","prompt":"On award of contract for civil works, did DDSE hold a coordinating meeting with the contractor to determine implementation modalities?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Did DLOG/DPROC forward the project documents to DDSE and the benefiting Command/establishment before commencement?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Did the benefiting Command hand over the site to the contractor?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are project officers supervising and monitoring the project from commencement to completion, with weekly reports rendered to DLOG/DPROC and DDSE through their Acting Authorities?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are benefiting establishments forwarding weekly reports and pictures of ongoing projects (hard and soft copies) to DHQ (DLOG/DPROC and DDSE)?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are project officers reporting to their Principal on ongoing projects, copying the Director of Projects and DDSE?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Did DDAB inform DLOG/DPROC and DDSE as soon as the contractor was paid mobilisation fee and other stage payments?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Did DLOG/DPROC carry out a soil test before coming up with the design and BOQ, with the report forwarded to DDSE?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Is the BOQ detailed with each item clearly specified rather than lumped together?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Has the contractor submitted a sealed undertaking by a COREN-certified civil/structural engineer accepting responsibility for structural work?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Have Gantt charts / programme of works been made available by the contractor to Log Branch and DDSE before commencement?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Do the concrete and blocks used meet the specified mix and strength requirements?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Have the contractors presented all architectural and engineering drawings to DDSE during the coordinating meeting for analysis?","responseType":"yes_no","weight":10},{"code":"15","prompt":"For storey buildings, was the frame (slabs, beams, columns) constructed up to roofing level before block work?","responseType":"yes_no","weight":10},{"code":"16","prompt":"Has the contractor shown evidence of varied sources of procurement of materials to ensure quality and standards?","responseType":"yes_no","weight":10},{"code":"17","prompt":"For buildings being handed over, have pressure testing of plumbing works and testing of electrical works been carried out?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Where clusters of projects exist, has a project-monitoring team been constituted for day-to-day inspection under the DDSE Project Officer?","responseType":"yes_no","weight":10},{"code":"19","prompt":"Is the project-monitoring team working directly with DLOG/DPROC and DDSE?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Are approved designs and BOQs being adhered to without unauthorised alteration?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Were final inspections jointly conducted by DLOG/DPROC and DDSE?","responseType":"yes_no","weight":10},{"code":"22","prompt":"Did any job-correction advisory letters or stop-work orders emanate from DLOG/DPROC and DDSE (as required)?","responseType":"yes_no","weight":10}]},{"title":"Project Description & Documentation","items":[{"code":"1","prompt":"Project cost — is the project split into phases, and is the amount part or full project cost?","responseType":"narrative","weight":10},{"code":"2","prompt":"Project goal(s) — what are the specific goals/objectives of the project?","responseType":"narrative","weight":10},{"code":"3","prompt":"Project location — what is the specific location, executing unit and benefiting unit?","responseType":"narrative","weight":10},{"code":"4","prompt":"Project duration — from release of funds to completion/handover, what is the duration?","responseType":"narrative","weight":10},{"code":"5","prompt":"Resources used to implement the project — what are the funding sources, including any additional sources and amounts?","responseType":"narrative","weight":10},{"code":"6","prompt":"Expected short-term and long-term outcomes — how well has the project performed against expected benefits?","responseType":"narrative","weight":10}]},{"title":"Conduct of Evaluation","items":[{"code":"1","prompt":"Project implementation plan — design: what is the design concept, who made it, and was it approved per accepted standards?","responseType":"narrative","weight":10},{"code":"2","prompt":"Project implementation plan — work programme: does the executing unit have a work programme to monitor progress?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Project implementation plan — manpower: is skilled manpower (masons, electricians, plumbers, carpenters, artisans) sufficient in size and quality?","responseType":"narrative","weight":10},{"code":"4","prompt":"Physical inspection and progress of work — have the BOQ, drawings and specifications been collected and studied?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Adherence to specifications — does the work done match the standards specified in the BOQ, drawings and specifications?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Quality of work done — how does the quality measure against set standards?","responseType":"narrative","weight":10},{"code":"7","prompt":"Reconciliation of account records with work done — does the project account balance reconcile with the measured cost of work done?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Likely time of completion — based on the work programme, cash flow and artisan skill, what is the likely completion time?","responseType":"narrative","weight":10},{"code":"9","prompt":"Observations, lapses and comments — what observations, lapses and comments does the evaluator record on preparation and execution?","responseType":"narrative","weight":10},{"code":"10","prompt":"Has the unit the capability to do direct labour, based on its manpower returns showing the various trades?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Were contractors or consultants used, and can this be confirmed from unit records or payments?","responseType":"narrative","weight":10}]},{"title":"Recommendation","items":[{"code":"1","prompt":"Is the formation/unit able to carry out the project?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is there a need to stop or continue with the project?","responseType":"narrative","weight":10},{"code":"3","prompt":"Is completion of the project possible?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Is a variation of the cost needed?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Has the project been concluded?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is there any other information that could assist the formation/unit in completing the project?","responseType":"narrative","weight":10}]},{"title":"Construction Work — Foundation","items":[{"code":"1","prompt":"Has the contractor provided a soil test report to determine the right foundation before excavation commences?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Was setting out done correctly with pegs, profile and line in accordance with the design?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Is the foundation trench depth staked out correctly as indicated in the drawing/BOQ?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Does the foundation footing/blinding thickness follow the design?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are the foundation footings straight and correctly positioned?","responseType":"yes_no","weight":10},{"code":"6","prompt":"For raft foundations, do the reinforcement iron rod sizes match the BOQ specification?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Was the correct laterite filling sand used during foundation filling (not sandy or loamy soil, and free of particles)?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Was the laterite watered/compacted repeatedly after filling until compaction was achieved?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Were hard-core and wire mesh used during foundation works?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Was a damp-proof membrane (DPM) or polythene vapour barrier laid to prevent dampness and water ingress?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Was the right quality of plumbing and electrical piping material used for conduit piping?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Does the cement/sand/granite mixture proportion match the BOQ specification?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Was the right plywood/chipboard panel form work used to secure columns before casting?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Was the cast Damp Proof Course (DPC) watered 12 hours later and consistently thereafter?","responseType":"yes_no","weight":10}]},{"title":"Construction Work — Block Laying","items":[{"code":"1","prompt":"Are all blocks made of stone dust material (concrete block)?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is the block work plumbed properly and laid straight?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Is there a satisfactory level of quality finish with no evidence of mortar splashes?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are all plumbing and electrical pipes conduit-installed and correctly positioned?","responseType":"yes_no","weight":10}]},{"title":"Construction Work — Decking","items":[{"code":"1","prompt":"Do the beams and columns follow through and align with the design and BOQ specification?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Do the reinforcement iron rods and sand/cement/granite mixture ratio match the BOQ specification (any reduction amounts to a contract violation)?","responseType":"yes_no","weight":10}]},{"title":"Construction Work — Roofing","items":[{"code":"1","prompt":"Have all roofing timber members undergone preventive treatment and been laid straight, true and fixed correctly?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is fixing/screwing done evenly and neatly?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are all tie beams, purlins, rafters and ridge caps placed accurately?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are all noggins level with each other?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is the correct gauge supplied for the long-span or other roofing cover per the BOQ specification?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is the thickness of POP ceiling work at least 2 inches?","responseType":"yes_no","weight":10}]},{"title":"Construction Work — Plastering & External Cladding","items":[{"code":"1","prompt":"Was the right plastering sand used and correctly filtered with a good mix proportion?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Was cladding installed per manufacturer construction manuals with no damaged panels used?","responseType":"yes_no","weight":10}]},{"title":"Construction Work — General Finishes","items":[{"code":"1","prompt":"Are all doors, windows, tiling, electrical and sanitary wares laid properly per the BOQ specification?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Has the contractor provided company evidence for purchase of paint materials before use, per the BOQ recommendation/specification?","responseType":"yes_no","weight":10}]},{"title":"Construction Work — Fencing","items":[{"code":"1","prompt":"Does the excavation depth reach the minimum level beneath ground level?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is a column base provided for each column?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are intervals between columns no more than 3.5 metres?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are expansion joints introduced at wall intervals to allow for ground movement?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is the fence height at least 3 metres?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is coping introduced at the top of the fence with iron rods and formwork cast for a flat base and good aesthetics?","responseType":"yes_no","weight":10}]}]}'::jsonb WHERE code = 'civil_projects';
UPDATE public.modules SET template = '{"sections":[{"title":"General Work Environment","items":[{"code":"1","prompt":"Are all worksites clean and orderly?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are work surfaces kept dry, or are appropriate means taken to assure the surfaces are slip-resistant?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are all spilled materials or liquids cleaned up immediately?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Is combustible scrap, debris and waste stored safely and removed from the worksite promptly?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is accumulated combustible dust routinely removed from elevated surfaces, including the overhead structure of buildings?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is combustible dust cleaned up with a vacuum system to prevent the dust going into suspension?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Is metallic or conductive dust prevented from entering or accumulating on or around electrical enclosures or equipment?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are covered metal waste cans used for oily and paint-soaked waste?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Are all oil and gas fired devices equipped with flame failure controls that prevent fuel flow if pilots or main burners are not working?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are paint spray booths, dip tanks and the like cleaned regularly?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are the minimum number of toilets and washing facilities provided?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Are all toilets and washing facilities clean and sanitary?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are all work areas adequately illuminated?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Are pits and floor openings covered or otherwise guarded?","responseType":"yes_no","weight":10}]},{"title":"Walkways","items":[{"code":"1","prompt":"Are aisles and passageways kept clear?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are aisles and walkways marked as appropriate?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are wet surfaces covered with non-slip materials?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are holes in the floor, sidewalk or other walking surface repaired properly, covered or otherwise made safe?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is there safe clearance for walking in aisles where motorised or mechanical handling equipment is operating?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are spilled materials cleaned up immediately?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are materials or equipment stored so that sharp projectiles will not interfere with the walkway?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are changes of direction or elevation readily identifiable?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Are aisles/walkways near moving machinery, welding or similar operations arranged so employees are not subjected to hazards?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Is adequate headroom provided for the entire length of any aisle or walkway?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are standard guardrails provided wherever aisle or walkway surfaces are elevated more than 30 inches above any adjacent floor or ground?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Are bridges provided over conveyors and similar hazards?","responseType":"yes_no","weight":10}]},{"title":"Floor & Wall Stairways","items":[{"code":"1","prompt":"Are floor openings guarded by a cover, guardrail, or equivalent on all sides (except at stairway/ladder entrances)?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are toe boards installed around the edges of a permanent floor opening where persons may pass below?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are skylight screens constructed and mounted to withstand a load of at least 200 pounds?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Is glass in windows, doors and glass walls subject to human impact of sufficient thickness and type for the condition of use?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are grates or similar covers over floor openings (e.g. floor drains) designed so foot traffic or rolling equipment is unaffected by the grate spacing?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are unused portions of service pits, and pits not in use, covered or protected by guardrails or equivalent?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are manhole/trench covers (and supports) in roadways designed to carry a truck rear-axle load of at least 20,000 pounds?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are floor or wall openings in fire-resistive construction fitted with doors/covers compatible with the fire rating, with self-closing features where appropriate?","responseType":"yes_no","weight":10}]},{"title":"Stairs & Stairways","items":[{"code":"1","prompt":"Are standard stair rails or handrails fitted on all stairways with four or more risers?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are all stairways at least 22 inches wide?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Do stairs have at least 6′6\" overhead clearance?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Do stairs angle no more than 50 and no less than 30 degrees?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are hollow-pan type treads and landings filled to nosing level with solid material?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are step risers uniform from top to bottom, with no riser spacing greater than 7-1/2 inches?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are steps designed or provided with a slip-resistant surface?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are stairway handrails located between 30 and 34 inches above the leading edge of stair treads?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Do stairway handrails have at least 1-1/2 inches of clearance from the wall or mounting surface?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are stairway handrails capable of withstanding a load of 200 pounds, applied in any direction?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Where stairs exit directly into a vehicle-operating area, are adequate barriers and warnings provided?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Do stairway landings have a travel-direction dimension at least equal to the width of the stairway?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Is the vertical distance between stairway landings limited to 12 feet or less?","responseType":"yes_no","weight":10}]},{"title":"Elevated Surfaces","items":[{"code":"1","prompt":"Are signs posted, when appropriate, showing the elevated surface load capacity?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are surfaces elevated more than 30 inches above the floor or ground provided with standard guardrails?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are elevated surfaces beneath which people or machinery could be exposed to falling objects provided with standard 4-inch toeboards?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Is a permanent means of access and egress provided to elevated storage and work surfaces?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is required headroom provided where necessary?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is material on elevated surfaces piled, stacked or racked to prevent tipping, falling, collapsing, rolling or spreading?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are dock boards or bridge plates used when transferring materials between docks and trucks or rail cars?","responseType":"yes_no","weight":10}]},{"title":"Exiting / Egress","items":[{"code":"1","prompt":"Are all exits marked with an exit sign and illuminated by a reliable light source?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are directions to exits, when not immediately apparent, marked with visible signs?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are doors/passageways/stairways that could be mistaken for exits appropriately marked (\"NOT AN EXIT\", \"TO BASEMENT\", \"STOREROOM\", etc.)?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Do exit signs show the word \"EXIT\" in lettering at least 5 inches high with a stroke at least 1/2 inch wide?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are exit doors side-hinged?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are all exits kept free of obstructions?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are at least two means of egress provided from elevated platforms, pits or rooms where a second exit reduces risk of injury from hazardous substances?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are there sufficient exits to permit prompt escape in an emergency?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Are special precautions taken to protect employees during construction and repair operations?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Is the number of exits from each floor and from the building itself appropriate for the building occupancy load?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are exit stairways enclosed by fire-resistive construction appropriate to the building height (2-hour if over 4 storeys, 1-hour elsewhere)?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Where ramps are used as part of required exiting, is the slope limited to 1-foot vertical per 12 feet horizontal?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Where exiting is through frameless/glass exit doors, are the doors fully tempered and meeting human-impact safety requirements?","responseType":"yes_no","weight":10}]},{"title":"Exit Doors","items":[{"code":"1","prompt":"Are doors required to serve as exits designed so the way of exit travel is obvious and direct?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are windows that could be mistaken for exit doors made inaccessible by barriers or railings?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are exit doors openable from the direction of exit travel without a key or special knowledge/effort while the building is occupied?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Is a revolving, sliding or overhead door prohibited from serving as a required exit door?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Where panic hardware is installed on a required exit door, does it open with a force of 15 pounds or less in the direction of exit travel?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are doors on cold storage rooms fitted with an inside release that opens the door even if padlocked/locked outside?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Where exit doors open directly onto a street/alley/vehicle area, are adequate barriers and warnings provided?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are doors that swing both ways between high-traffic rooms fitted with viewing panels?","responseType":"yes_no","weight":10}]},{"title":"Environmental Controls","items":[{"code":"1","prompt":"Are all work areas properly illuminated?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are employees instructed in proper first aid and other emergency procedures?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are hazardous substances identified that may cause harm by inhalation, ingestion, skin absorption or contact?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are employees aware of the hazards of chemicals they may be exposed to (ammonia, chlorine, epoxies, caustics, etc.)?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is employee exposure to chemicals in the workplace kept within acceptable levels?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Can a less harmful method or product be used?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Is the work area’s ventilation system appropriate for the work performed?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are spray painting operations done in spray rooms/booths with an appropriate exhaust system?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Is employee exposure to welding fumes controlled by ventilation, respirators, exposure time or other means?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are welders and nearby workers provided with flash shields during welding operations?","responseType":"yes_no","weight":10},{"code":"11","prompt":"If forklifts/vehicles are used in enclosed areas, are carbon monoxide levels kept below the maximum acceptable concentration?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Has it been determined that noise levels in the facilities are within acceptable levels?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are engineering controls used to reduce excessive noise levels?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Are proper precautions taken when handling asbestos and other fibrous materials?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Are caution labels and signs used to warn of asbestos?","responseType":"yes_no","weight":10},{"code":"16","prompt":"Are wet methods used, when practicable, to prevent emission of airborne asbestos fibres, silica dust and similar hazards?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Is vacuuming with appropriate equipment used rather than blowing or sweeping dust, whenever possible?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Are grinders, saws and other dust-producing machines vented to an industrial collector or central exhaust system?","responseType":"yes_no","weight":10},{"code":"19","prompt":"Are local exhaust ventilation systems designed and operating properly, with ducts free of obstructions and belts not slipping?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Is personal protective equipment provided, used and maintained wherever required?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Are there written SOPs for the selection and use of respirators where needed?","responseType":"yes_no","weight":10},{"code":"22","prompt":"Are restrooms and washrooms kept clean and sanitary?","responseType":"yes_no","weight":10},{"code":"23","prompt":"Is all water provided for drinking, washing and cooking potable?","responseType":"yes_no","weight":10},{"code":"24","prompt":"Are outlets for non-potable water clearly identified?","responseType":"yes_no","weight":10},{"code":"25","prompt":"Are employees’ physical capacities assessed before assignment to jobs requiring heavy work?","responseType":"yes_no","weight":10},{"code":"26","prompt":"Are employees instructed in the proper manner of lifting heavy objects?","responseType":"yes_no","weight":10},{"code":"27","prompt":"Where heat is a problem, are fixed work areas provided with spot cooling or air conditioning?","responseType":"yes_no","weight":10},{"code":"28","prompt":"Are employees screened before assignment to high-heat areas for susceptibility to adverse reaction?","responseType":"yes_no","weight":10},{"code":"29","prompt":"Are employees exposed to traffic hazards required to wear bright-coloured (traffic orange) warning vests?","responseType":"yes_no","weight":10},{"code":"30","prompt":"Are exhaust stacks and air intakes positioned so contaminated air will not be recirculated within an enclosed area?","responseType":"yes_no","weight":10},{"code":"31","prompt":"Is equipment producing ultra-violet radiation properly shielded?","responseType":"yes_no","weight":10}]},{"title":"Flammable & Combustible Materials","items":[{"code":"1","prompt":"Are combustible scrap, debris and waste materials (e.g. oily rags) stored in covered metal receptacles and removed from the worksite promptly?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is proper storage practiced to minimise the risk of fire, including spontaneous combustion?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are approved containers and tanks used for storage and handling of flammable/combustible liquids?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are all connections on drums and combustible liquid piping vapor- and liquid-tight?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are flammable liquids kept in closed containers when not in use?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are bulk drums of flammable liquids grounded and bonded to containers during dispensing?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Do storage rooms for flammable/combustible liquids have explosion-proof lights?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Do storage rooms for flammable/combustible liquids have mechanical or gravity ventilation?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Is liquefied petroleum gas stored, handled and used per safe practices and standards?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are liquefied petroleum storage tanks guarded to prevent vehicle damage?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are solvent wastes and flammable liquids kept in fire-resistant covered containers until removed from the worksite?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Is vacuuming used rather than blowing or sweeping combustible dust, whenever possible?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are fire separators placed between stacked containers of combustibles/flammables to assure support and stability?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Are fuel gas cylinders and oxygen cylinders separated by distance or fire-resistant barriers while in storage?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Are fire extinguishers selected and provided for the material classes present (A/B/C)?","responseType":"yes_no","weight":10},{"code":"16","prompt":"If a Halon 1301 extinguisher is used, can employees evacuate within its specified time?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Are appropriate fire extinguishers mounted within 75 feet of outside flammable-liquid areas and within 10 feet of inside storage areas?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Is transfer/withdrawal of flammable or combustible liquids performed by trained personnel?","responseType":"yes_no","weight":10},{"code":"19","prompt":"Are fire extinguishers mounted so employees travel no more than 75 feet for a class \"A\" fire or 50 feet for a class \"B\" fire?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Are employees trained in the use of fire extinguishers?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Are extinguishers free from obstruction or blockage?","responseType":"yes_no","weight":10},{"code":"22","prompt":"Are all extinguishers serviced, maintained and tagged at intervals not exceeding one year?","responseType":"yes_no","weight":10},{"code":"23","prompt":"Are all extinguishers fully charged and in their designated places?","responseType":"yes_no","weight":10},{"code":"24","prompt":"Is a record maintained of required monthly extinguisher checks?","responseType":"yes_no","weight":10},{"code":"25","prompt":"Where sprinkler systems are installed, are nozzle heads arranged so water is not sprayed into operating electrical switchboards?","responseType":"yes_no","weight":10},{"code":"26","prompt":"Are \"NO SMOKING\" signs posted where appropriate near flammable/combustible materials?","responseType":"yes_no","weight":10},{"code":"27","prompt":"Are \"NO SMOKING\" signs posted on liquefied petroleum gas tanks?","responseType":"yes_no","weight":10},{"code":"28","prompt":"Are \"NO SMOKING\" rules enforced in flammable-material storage and use areas?","responseType":"yes_no","weight":10},{"code":"29","prompt":"Are safety cans used for dispensing flammable/combustible liquids at point of use?","responseType":"yes_no","weight":10},{"code":"30","prompt":"Are all spills of flammable/combustible liquids cleaned up promptly?","responseType":"yes_no","weight":10},{"code":"31","prompt":"Are storage tanks adequately vented to prevent excessive vacuum/pressure from filling, emptying or temperature changes?","responseType":"yes_no","weight":10},{"code":"32","prompt":"Are storage tanks equipped with emergency venting to relieve excessive pressure from fire exposure?","responseType":"yes_no","weight":10},{"code":"33","prompt":"Are spare portable/butane tanks used by industrial trucks stored per regulations?","responseType":"yes_no","weight":10}]},{"title":"Fire Protection","items":[{"code":"1","prompt":"Is there a fire prevention plan?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Does the plan describe the type of fire protection equipment and/or systems?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Have practices and procedures been established to control potential fire hazards and ignition sources?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are employees aware of the fire hazards of the materials and processes they are exposed to?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is the local fire department well acquainted with the facility, its location and specific hazards?","responseType":"yes_no","weight":10},{"code":"6","prompt":"If a fire alarm system exists, is it tested at least annually?","responseType":"yes_no","weight":10},{"code":"7","prompt":"If a fire alarm system exists, is it certified as required?","responseType":"yes_no","weight":10},{"code":"8","prompt":"If interior standpipes and valves exist, are they inspected regularly?","responseType":"yes_no","weight":10},{"code":"9","prompt":"If outside private fire hydrants exist, are they flushed at least once a year on a routine maintenance schedule?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are fire doors and shutters in good operating condition?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are fire doors and shutters unobstructed and protected, including their counterweights?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Are fire door and shutter fusible links in place?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are automatic sprinkler system water control valves, air and water pressures checked as required?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Is maintenance of the automatic sprinkler system assigned to a responsible person or contractor?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Are sprinkler heads protected by metal guards where exposed to physical damage?","responseType":"yes_no","weight":10},{"code":"16","prompt":"Is proper clearance maintained below sprinkler heads?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Are portable fire extinguishers provided in adequate number and type?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Are fire extinguishers mounted in readily accessible locations?","responseType":"yes_no","weight":10},{"code":"19","prompt":"Are fire extinguishers recharged regularly with the inspection tag noted?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Are employees periodically instructed in extinguisher use and fire protection procedures?","responseType":"yes_no","weight":10}]},{"title":"Hazardous Chemical Exposures","items":[{"code":"1","prompt":"Are employees trained in safe handling of hazardous chemicals (acids, caustics, etc.)?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are employees aware of the hazards of chemicals stored/used in the workplace (acids, bases, caustics, epoxies, phenols)?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Is employee exposure to chemicals kept within acceptable levels?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are eye wash fountains and safety showers provided where corrosive chemicals are handled?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are containers such as vats and storage tanks labelled as to their contents?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are employees required to use PPE (gloves, eye protection, respirators) when handling chemicals?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are flammable or toxic chemicals kept in closed containers when not in use?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are chemical piping systems clearly marked as to content?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Where corrosive liquids are handled in open containers, is adequate means available for neutralising/disposing of spills safely?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are standard operating procedures established and followed for cleaning up chemical spills?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Where needed for emergency use, are respirators stored in a clean, sanitary, convenient location?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Are emergency-use respirators adequate for the various uses they may be needed for?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are employees prohibited from eating in areas where hazardous chemicals are present?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Is PPE provided, used and maintained whenever necessary?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Are there written SOPs for the selection and use of respirators where needed?","responseType":"yes_no","weight":10},{"code":"16","prompt":"Are employees instructed on correct usage and limitations of respirators under a respirator protection programme?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Are the respirators approved for the particular application?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Are respirators regularly inspected, cleaned, sanitised and maintained?","responseType":"yes_no","weight":10},{"code":"19","prompt":"If hazardous substances are used in processes, is a medical or biological monitoring system in operation?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Are Threshold Limit Values / Permissible Exposure Limits for airborne contaminants known and applied?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Have control procedures (respirators, ventilation, handling practices) been instituted for hazardous materials?","responseType":"yes_no","weight":10},{"code":"22","prompt":"Are hazardous substances handled, whenever possible, in properly designed and exhausted booths or similar locations?","responseType":"yes_no","weight":10},{"code":"23","prompt":"Are dilution or local exhaust ventilation systems used to control dusts, vapours, gases, fumes, smoke, solvents or mists?","responseType":"yes_no","weight":10},{"code":"24","prompt":"Is ventilation equipment provided and operating properly for grinding, buffing, spray painting or vapor degreasing?","responseType":"yes_no","weight":10},{"code":"25","prompt":"Do employees complain of dizziness, headaches, nausea or irritation when using solvents or other chemicals?","responseType":"yes_no","weight":10},{"code":"26","prompt":"Is there a dermatitis problem — do employees complain of skin dryness, irritation or sensitisation?","responseType":"yes_no","weight":10},{"code":"27","prompt":"Has the use of an industrial hygienist or environmental health specialist been considered to evaluate operations?","responseType":"yes_no","weight":10},{"code":"28","prompt":"If internal combustion engines are used, is carbon monoxide kept within acceptable levels?","responseType":"yes_no","weight":10},{"code":"29","prompt":"Is vacuuming used rather than blowing or sweeping dust for clean-up, whenever possible?","responseType":"yes_no","weight":10},{"code":"30","prompt":"Are materials giving off toxic, asphyxiant, suffocating or anaesthetic fumes stored in remote/isolated locations when not in use?","responseType":"yes_no","weight":10}]},{"title":"Hazardous Substances Communication","items":[{"code":"1","prompt":"Is there a list of hazardous substances used in the workplace?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is there a written hazard communication programme covering MSDS labelling and employee training?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Is responsibility for MSDSs, container labelling and employee training clearly assigned?","responseType":"narrative","weight":10},{"code":"4","prompt":"Is each hazardous-substance container labelled with product identity and hazard warning?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is a Material Safety Data Sheet readily available for each hazardous substance used?","responseType":"yes_no","weight":10},{"code":"6","prompt":"How are other employers whose employees share the work area informed of hazardous substances present?","responseType":"narrative","weight":10},{"code":"7","prompt":"Is there an employee training programme for hazardous substances?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Does the training explain what an MSDS is and how to use/obtain one?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Does the training cover MSDS contents for each hazardous substance or class of substances?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Does the training explain \"Right to Know\"?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Does the training identify where employees can see the written hazard communication programme and where hazardous substances are present?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Does the training cover the physical and health hazards of substances, detection methods and protective measures?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Does the training cover details of the hazard communication programme, including labelling and MSDS use?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Does the training cover how employees are informed of hazards from non-routine tasks and unlabelled pipes?","responseType":"yes_no","weight":10}]},{"title":"Electrical","items":[{"code":"1","prompt":"Are workplace electricians familiar with the applicable electrical safety orders?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Is compliance with the applicable electrical code specified for all contract electrical work?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are employees required to promptly report obvious electrical hazards to life or property?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are employees instructed to make preliminary inspections/tests before starting work on electrical equipment or lines?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are switches opened, locked-out and tagged whenever electrical equipment/lines are serviced, maintained or adjusted?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are portable electrical tools and equipment grounded or double-insulated?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are electrical appliances (vacuum cleaners, polishers, vending machines) grounded?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Do extension cords in use have a grounding conductor?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Are multiple plug adapters prohibited?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are ground-fault circuit interrupters installed on temporary circuits at construction/demolition/alteration/excavation locations?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are all temporary circuits protected by suitable disconnecting switches or plug connectors at the junction with permanent wiring?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Is exposed wiring/cords with frayed or deteriorated insulation repaired or replaced promptly?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are flexible cords and cables free of splices or taps?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Are clamps or securing means provided on flexible cords/cables at plugs, receptacles, tools and equipment?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Are all cord, cable and raceway connections intact and secure?","responseType":"yes_no","weight":10},{"code":"16","prompt":"In wet or damp locations, are electrical tools and equipment appropriate for the location or otherwise protected?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Is the location of power lines and cables determined before digging, drilling or similar work begins?","responseType":"yes_no","weight":10},{"code":"18","prompt":"Are metal measuring tapes/ropes/handlines with metallic thread prohibited near energized equipment or circuit conductors?","responseType":"yes_no","weight":10},{"code":"19","prompt":"Is the use of metal ladders prohibited where the ladder or user could contact energized parts?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Are disconnecting switches and circuit breakers labelled to indicate their use or equipment served?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Are disconnecting means always opened before fuses are replaced?","responseType":"yes_no","weight":10},{"code":"22","prompt":"Do interior wiring systems include provisions for grounding metal parts of raceways, equipment and enclosures?","responseType":"yes_no","weight":10},{"code":"23","prompt":"Are all electrical raceways and enclosures securely fastened in place?","responseType":"yes_no","weight":10},{"code":"24","prompt":"Are all energized parts of electrical circuits and equipment guarded against accidental contact?","responseType":"yes_no","weight":10},{"code":"25","prompt":"Is sufficient access and working space maintained about electrical equipment for safe operation and maintenance?","responseType":"yes_no","weight":10},{"code":"26","prompt":"Are unused openings in electrical enclosures and fittings closed with appropriate covers, plugs or plates?","responseType":"yes_no","weight":10},{"code":"27","prompt":"Are electrical enclosures (switches, receptacles, junction boxes) provided with tight-fitting covers or plates?","responseType":"yes_no","weight":10},{"code":"28","prompt":"Are disconnecting switches for motors over two horsepower rated to open the circuit without exploding when stalled?","responseType":"yes_no","weight":10},{"code":"29","prompt":"Is low voltage protection provided on motor control devices where inadvertent starting could cause injury?","responseType":"yes_no","weight":10},{"code":"30","prompt":"Is each motor disconnecting switch or circuit breaker located within sight of the motor control device?","responseType":"yes_no","weight":10},{"code":"31","prompt":"Is the controller for each motor over two horsepower rated equal to or above the motor’s horsepower?","responseType":"yes_no","weight":10},{"code":"32","prompt":"Are employees who regularly work on or near energized equipment instructed in CPR?","responseType":"yes_no","weight":10},{"code":"33","prompt":"Are employees prohibited from working alone on energized lines or equipment over 600 volts?","responseType":"yes_no","weight":10}]},{"title":"Noise","items":[{"code":"1","prompt":"Are there areas where continuous noise levels exceed 85 dBA?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are noise levels measured using a sound level meter or octave band analyzer, with records kept?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Has isolating noisy machinery from the rest of the operation been tried?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Have engineering controls been used to reduce excessive noise levels?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Where engineering controls are not feasible, are administrative controls (e.g. worker rotation) used to minimise exposure?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is there an ongoing preventive health programme educating employees on safe noise levels and use of personal protection?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Is the training repeated annually for employees exposed to continuous noise above 85 dBA?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Have work areas where noise makes voice communication difficult been identified and posted?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Is approved hearing protective equipment available to every employee in areas exceeding 85 dBA?","responseType":"yes_no","weight":10},{"code":"10","prompt":"If ear protectors are used, are employees properly fitted and instructed in their use and care?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are employees exposed to continuous noise above 85 dBA given periodic audiometric testing?","responseType":"yes_no","weight":10}]},{"title":"Fueling","items":[{"code":"1","prompt":"Is it prohibited to fuel an internal combustion engine with a flammable liquid while the engine is running?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are fueling operations conducted so spillage likelihood is minimal?","responseType":"yes_no","weight":10},{"code":"3","prompt":"When spillage occurs, is fuel cleaned up/evaporated or vapors controlled before restarting the engine?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are fuel tank caps replaced and secured before starting the engine?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is there always metal contact between container and fuel tank during fueling?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are fueling hoses of a type designed to handle the specific fuel?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Is it prohibited to handle or transfer gasoline in open containers?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are open lights, flames, or sparking/arcing equipment prohibited near fueling operations?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Is smoking prohibited in the vicinity of fueling operations?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are fueling operations prohibited in buildings/enclosed areas not specifically ventilated for the purpose?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Where fueling is via gravity flow, are the nozzles self-closing?","responseType":"yes_no","weight":10}]},{"title":"Identification of Piping Systems","items":[{"code":"1","prompt":"Where non-potable water is piped, are outlets/taps posted to warn against drinking, washing or personal use?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are above-ground hazardous-substance pipelines identified at points where confusion could introduce hazards?","responseType":"yes_no","weight":10},{"code":"3","prompt":"When pipelines are colour-painted, are all visible parts of the line identified?","responseType":"yes_no","weight":10},{"code":"4","prompt":"When pipelines use colour bands/tapes, are they at reasonable intervals and at each outlet/valve/connection?","responseType":"yes_no","weight":10},{"code":"5","prompt":"When pipelines are identified by colour, is the colour code posted where confusion could introduce hazards?","responseType":"yes_no","weight":10},{"code":"6","prompt":"When pipeline contents are identified by name/abbreviation, is the information readily visible near each valve/outlet?","responseType":"yes_no","weight":10},{"code":"7","prompt":"When hazardous-substance pipelines use tags, are the tags durable, clearly legible and installed at each valve/outlet?","responseType":"yes_no","weight":10},{"code":"8","prompt":"When pipelines are heated by electricity, steam or another source, are suitable warning signs/tags placed at serviceable parts?","responseType":"yes_no","weight":10}]},{"title":"Material Handling","items":[{"code":"1","prompt":"Is there safe clearance for equipment through aisles and doorways?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are aisleways designated, permanently marked, and kept clear for unhindered passage?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are motorised vehicles and mechanised equipment inspected daily or prior to use?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are vehicles shut off and brakes set prior to loading or unloading?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are stacked containers of combustibles/flammables always separated by sufficient dunnage for stability?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are dock boards (bridge plates) used when loading/unloading between vehicles and docks?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are trucks and trailers secured from movement during loading and unloading?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Are dock plates and loading ramps built and maintained to support the imposed loading?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Are hand trucks maintained in safe operating condition?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are chutes equipped with sideboards of sufficient height to prevent materials falling off?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are chutes and gravity roller sections firmly placed or secured to prevent displacement?","responseType":"yes_no","weight":10},{"code":"12","prompt":"At the delivery end of rollers or chutes, are provisions made to brake the movement of handled materials?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are pallets usually inspected before being loaded or moved?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Are hooks with safety latches or similar arrangements used when hoisting materials to prevent slings slipping off?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Are securing chains, ropes, chokers or slings adequate for the job?","responseType":"yes_no","weight":10},{"code":"16","prompt":"When hoisting material/equipment, are provisions made to ensure no one passes under suspended loads?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Are Material Safety Data Sheets available to employees handling hazardous substances?","responseType":"yes_no","weight":10}]},{"title":"Transporting Employees & Materials","items":[{"code":"1","prompt":"Do employees who operate vehicles on public thoroughfares hold valid operator licences?","responseType":"yes_no","weight":10},{"code":"2","prompt":"When 7+ employees are regularly transported, is the operator’s licence appropriate for the vehicle class?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Is each van/bus/truck used to transport employees equipped with an adequate number of seats?","responseType":"yes_no","weight":10},{"code":"4","prompt":"When employees are transported by truck, are provisions made to prevent falling from the vehicle?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Are transport vehicles equipped with lamps, brakes, horns, mirrors, windshields and turn signals in good repair?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are transport vehicles fitted with handrails, steps, stirrups or similar for safe mounting/dismounting?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Are employee transport vehicles equipped at all times with at least two reflective flares?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Is a fully charged fire extinguisher (at least 4 B:C rating) maintained in each employee transport vehicle?","responseType":"yes_no","weight":10},{"code":"9","prompt":"When sharp-edged cutting tools are carried in passenger compartments, are they in closed, secured boxes/containers?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Are employees prohibited from riding on top of a load that can shift, topple or become unstable?","responseType":"yes_no","weight":10}]},{"title":"Control of Harmful Substances by Ventilation","items":[{"code":"1","prompt":"Is the volume and velocity of air in each exhaust system sufficient to gather and convey contaminants to disposal?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are exhaust inlets, ducts and plenums designed and supported to prevent collapse or failure?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are clean-out ports or doors provided at intervals not exceeding 12 feet in horizontal exhaust duct runs?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Where two or more operations share an exhaust system, could the combination of substances create a fire/explosion/reaction hazard in the duct?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is adequate makeup air provided to areas where exhaust systems are operating?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is the makeup-air intake located so only clean, contaminant-free air enters the work environment?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Where two or more ventilation systems serve a work area, does one avoid offsetting the function of the other?","responseType":"yes_no","weight":10}]},{"title":"Sanitizing Equipment & Clothing","items":[{"code":"1","prompt":"Is required PPE or clothing of a type that can be easily cleaned and disinfected?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Are employees prohibited from interchanging PPE/clothing unless properly cleaned?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are machines/equipment that handle injurious materials cleaned/decontaminated before overhaul or storage?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Are employees prohibited from smoking or eating where injurious contaminants are present?","responseType":"yes_no","weight":10},{"code":"5","prompt":"When changing into protective clothing, is a clean changeroom with separate storage for street/protective clothing provided?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are employees required to shower and wash hair as soon as possible after known contact with a carcinogen?","responseType":"yes_no","weight":10},{"code":"7","prompt":"When equipment/materials are moved into or out of a carcinogen-regulated area, is contamination of other areas prevented?","responseType":"yes_no","weight":10}]},{"title":"Confined Spaces","items":[{"code":"1","prompt":"Are confined spaces thoroughly emptied of corrosive or hazardous substances before entry?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Before entry, are lines containing inert, toxic, flammable or corrosive materials valved off, blanked or disconnected?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Are impellers, agitators or other moving equipment inside confined spaces locked-out if they present a hazard?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Is natural or mechanical ventilation provided prior to confined-space entry?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Before entry, are atmospheric tests performed for oxygen deficiency, toxic substances and explosive concentrations?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Is adequate illumination provided for work performed in the confined space?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Is the atmosphere inside the confined space frequently tested or continuously monitored during work?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Is a standby employee assigned outside the confined space to watch work, sound an alarm and render assistance?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Are the standby employee and others prohibited from entering without lifelines/respiratory equipment if there is doubt about an emergency’s cause?","responseType":"yes_no","weight":10},{"code":"10","prompt":"In addition to the standby employee, is at least one other trained rescuer in the vicinity?","responseType":"yes_no","weight":10},{"code":"11","prompt":"Are all rescuers appropriately trained and using approved, recently inspected equipment?","responseType":"yes_no","weight":10},{"code":"12","prompt":"Does rescue equipment allow for lifting employees vertically from a top opening?","responseType":"yes_no","weight":10},{"code":"13","prompt":"Are personnel trained in First Aid and CPR immediately available?","responseType":"yes_no","weight":10},{"code":"14","prompt":"Is there an effective communication system whenever respiratory equipment is used and the worker is out of sight of the standby person?","responseType":"yes_no","weight":10},{"code":"15","prompt":"Is approved respiratory equipment required if the confined-space atmosphere cannot be made acceptable?","responseType":"yes_no","weight":10},{"code":"16","prompt":"Is all portable electrical equipment used inside confined spaces grounded/insulated or fitted with ground-fault protection?","responseType":"yes_no","weight":10},{"code":"17","prompt":"Before gas welding/burning in a confined space, are hoses checked for leaks and the area tested for explosive atmosphere before each entry with a lit torch?","responseType":"yes_no","weight":10},{"code":"18","prompt":"If oxygen-consuming equipment is used in a confined space, is sufficient air provided to keep oxygen concentration above 19.5%?","responseType":"yes_no","weight":10},{"code":"19","prompt":"Whenever combustion-type equipment is used in a confined space, are exhaust gases vented outside the enclosure?","responseType":"yes_no","weight":10},{"code":"20","prompt":"Is each confined space checked for decaying vegetation or animal matter that may produce methane?","responseType":"yes_no","weight":10},{"code":"21","prompt":"Is the confined space checked for possible industrial waste containing toxic properties?","responseType":"yes_no","weight":10},{"code":"22","prompt":"If the confined space is below ground near vehicle traffic, could vehicle exhaust or carbon monoxide enter the space?","responseType":"yes_no","weight":10},{"code":"23","prompt":"Do all drying spaces have adequate ventilation?","responseType":"yes_no","weight":10}]},{"title":"Emergency Action Plan","items":[{"code":"1","prompt":"Is an emergency action plan required and in place?","responseType":"yes_no","weight":10},{"code":"2","prompt":"Does the emergency action plan comply with the applicable regulatory requirements?","responseType":"yes_no","weight":10},{"code":"3","prompt":"Have emergency escape procedures and routes been developed and communicated to all employees?","responseType":"yes_no","weight":10},{"code":"4","prompt":"Do employees who remain to operate critical operations before evacuating know the proper procedures?","responseType":"yes_no","weight":10},{"code":"5","prompt":"Is the employee alarm system for emergency action recognisable and perceptible above ambient conditions?","responseType":"yes_no","weight":10},{"code":"6","prompt":"Are alarm systems properly maintained and tested regularly?","responseType":"yes_no","weight":10},{"code":"7","prompt":"Is the emergency action plan reviewed and revised periodically?","responseType":"yes_no","weight":10},{"code":"8","prompt":"Do employees know their responsibilities for reporting emergencies?","responseType":"yes_no","weight":10},{"code":"9","prompt":"Do employees know their responsibilities during an emergency?","responseType":"yes_no","weight":10},{"code":"10","prompt":"Do employees know their responsibilities for conducting rescue and medical duties?","responseType":"yes_no","weight":10}]}]}'::jsonb WHERE code = 'hazard_safety';
